// Compiled clinical knowledge base (SPEC §5, §10). The JSON files in ./data are generated by
// kb-src/build_kb.py from the cited research (see docs/CLINICAL-SOURCES.md); this module assembles them into
// one KnowledgeBase value and exposes the lookup API the engines and screens use. Pure: no React, no browser APIs.

import type { MetricKey } from "../model/types";
import type { DrugSelector, KbClass, KbCombo, KbDrug, KbSource } from "./types";
import { KB } from "./compiled";
import { matchDrugWithKb } from "./normalize";

export { KB, KB_NOT_ENCODED } from "./compiled";

// Lookups over the compiled KB. Built here (not with the review engine's indexKb) so the knowledge base does not
// depend on src/engine; the engine indexes the same KB value itself.
const drugById = new Map(KB.drugs.map((d) => [d.id, d]));
const sourceById = new Map(KB.sources.map((s) => [s.id, s]));
const classById = new Map(KB.classes.map((c) => [c.id, c]));
const comboById = new Map(KB.combos.map((c) => [c.id, c]));
const ancestorMemo = new Map<string, ReadonlySet<string>>();

function ancestors(classId: string, seen: Set<string> = new Set()): ReadonlySet<string> {
  const memo = ancestorMemo.get(classId);
  if (memo) return memo;
  const out = new Set<string>([classId]);
  if (seen.has(classId)) return out; // cycle guard
  seen.add(classId);
  for (const p of classById.get(classId)?.parents ?? []) for (const a of ancestors(p, seen)) out.add(a);
  ancestorMemo.set(classId, out);
  return out;
}

const classesMemo = new Map<string, ReadonlySet<string>>();
function classSet(ingredientId: string): ReadonlySet<string> {
  const memo = classesMemo.get(ingredientId);
  if (memo) return memo;
  const out = new Set<string>();
  for (const c of drugById.get(ingredientId)?.classes ?? []) for (const a of ancestors(c)) out.add(a);
  classesMemo.set(ingredientId, out);
  return out;
}

export function getDrug(id: string): KbDrug | undefined {
  return drugById.get(id);
}

export function getSource(id: string): KbSource | undefined {
  return sourceById.get(id);
}

export function getClass(id: string): KbClass | undefined {
  return classById.get(id);
}

export function getCombo(id: string): KbCombo | undefined {
  return comboById.get(id);
}

/** Direct classes of an ingredient plus every ancestor class (transitive). */
export function classesOf(ingredientId: string): string[] {
  return [...classSet(ingredientId)];
}

/** True when any ingredient is named by the selector or belongs (transitively) to one of its classes. */
export function selectorMatches(ingredientIds: string[], sel: DrugSelector): boolean {
  return ingredientIds.some((id) => sel.drugs?.includes(id) || (sel.classes ?? []).some((c) => classSet(id).has(c)));
}

/** Ingredient ids of every KB drug in a class (transitive). */
export function drugsInClass(classId: string): string[] {
  return KB.drugs.filter((d) => classSet(d.id).has(classId)).map((d) => d.id);
}

/** The KB lists this diary metric as a recognised effect of at least one of the ingredients. */
export function knownEffect(ingredientIds: string[], metric: MetricKey): boolean {
  return ingredientIds.some((id) => drugById.get(id)?.effects.includes(metric) ?? false);
}

export interface DrugSearchHit {
  label: string;
  detail: string;
  ingredientIds: string[];
  kind: "drug" | "brand" | "combo";
}

/** Suffixes printed in capitals on packaging ("Toprol XL", "Diovan HCT", "Claritin-D"). */
const CAPS = new Set(["xl", "xr", "er", "cr", "sr", "la", "cd", "hct", "pm", "ds", "odt", "hfa", "ac", "ib", "dm", "otc", "d", "ec", "sl", "xt", "hbp", "ir", "24hr", "12hr", "es", "lq", "ii", "iii"]);

/** "toprol xl" -> "Toprol XL", "claritin-d" -> "Claritin-D", "doan's pm" -> "Doan's PM". */
export function prettyName(name: string): string {
  return name
    .split(" ")
    .map((w) =>
      w
        .split("-")
        .map((p) => (CAPS.has(p) ? p.toUpperCase() : p ? p[0].toUpperCase() + p.slice(1) : p))
        .join("-"),
    )
    .join(" ");
}

function ingredientList(ids: string[]): string {
  return ids.map((id) => drugById.get(id)?.display.toLowerCase() ?? id).join(" + ");
}

function normQuery(s: string): string {
  return s.toLowerCase().replace(/[®™'’]/g, "").replace(/\s+/g, " ").trim();
}

interface Candidate {
  name: string;
  hit: DrugSearchHit;
  /** Lower ranks first among equal match quality: generics, then brands, then combinations. */
  kindRank: number;
}

let candidateCache: Candidate[] | null = null;

function candidates(): Candidate[] {
  if (candidateCache) return candidateCache;
  const out: Candidate[] = [];
  for (const d of KB.drugs) {
    out.push({ name: d.id, kindRank: 0, hit: { label: d.display, detail: d.usedFor, ingredientIds: [d.id], kind: "drug" } });
    for (const b of d.brands) {
      const label = prettyName(b);
      out.push({ name: b, kindRank: 1, hit: { label, detail: `${label} → ${d.display.toLowerCase()}`, ingredientIds: [d.id], kind: "brand" } });
    }
    for (const a of d.aliases) {
      const label = prettyName(a);
      out.push({ name: a, kindRank: 2, hit: { label, detail: `${label} → ${d.display.toLowerCase()}`, ingredientIds: [d.id], kind: "drug" } });
    }
  }
  for (const c of KB.combos) {
    const ingredients = ingredientList(c.ingredientIds);
    // Names that spell out the ingredients ("hydrocodone/acetaminophen") show the combination's display name.
    const isIngredientSpelling = (n: string) => c.ingredientIds.some((id) => n.includes(id.split(" ")[0]));
    const brandNames = c.names.filter((n) => !isIngredientSpelling(n) && !/^[a-z]+ [0-9]+$/.test(n)).map(prettyName);
    for (const n of new Set([...c.names, c.display.toLowerCase()])) {
      const spelled = isIngredientSpelling(n);
      const label = spelled ? c.display : prettyName(n);
      const detail = spelled ? `Combination${brandNames.length ? ` (e.g. ${brandNames.slice(0, 2).join(", ")})` : ""}: ${ingredients}` : `${label} → ${ingredients}`;
      out.push({ name: n, kindRank: 3, hit: { label, detail, ingredientIds: c.ingredientIds, kind: "combo" } });
    }
  }
  candidateCache = out;
  return out;
}

/**
 * Autocomplete over generics, brands, aliases and combination products. Exact matches rank first, then
 * prefix matches, then word-prefix, then substring; ties prefer generic names, then shorter labels (so
 * "Tylenol PM" comes before "Tylenol 8 Hr Arthritis Pain"), then alphabetical order. Each label appears once. When nothing matches, a close
 * spelling (fuzzy) is offered as a "Did you mean" hit.
 */
export function searchDrugs(query: string, limit = 8): DrugSearchHit[] {
  const q = normQuery(query);
  if (!q) return [];
  const scored: { hit: DrugSearchHit; score: number; kindRank: number }[] = [];
  for (const c of candidates()) {
    const n = c.name;
    let score: number;
    if (n === q) score = 0;
    else if (n.startsWith(q)) score = 1;
    else if (n.split(/[\s/+-]+/).some((w) => w.startsWith(q))) score = 2;
    else if (q.length >= 3 && n.includes(q)) score = 3;
    else continue;
    scored.push({ hit: c.hit, score, kindRank: c.kindRank });
  }
  scored.sort(
    (a, b) =>
      a.score - b.score ||
      Math.min(a.kindRank, 1) - Math.min(b.kindRank, 1) ||
      a.hit.label.length - b.hit.label.length ||
      a.kindRank - b.kindRank ||
      a.hit.label.localeCompare(b.hit.label),
  );
  const seen = new Set<string>();
  const out: DrugSearchHit[] = [];
  for (const s of scored) {
    const key = `${s.hit.label.toLowerCase().replace(/[^a-z0-9]+/g, "")}|${s.hit.ingredientIds.join("+")}`;
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(s.hit);
    if (out.length >= limit) break;
  }
  if (out.length === 0 && q.length >= 4) {
    const m = matchDrugWithKb(KB, q);
    if (m.match === "fuzzy" && m.suggestion) {
      out.push({ label: m.suggestion, detail: `Did you mean ${m.suggestion}?`, ingredientIds: m.ingredientIds, kind: m.ingredientIds.length > 1 ? "combo" : "drug" });
    }
  }
  return out;
}

/** Honest coverage counts for the How-it-works page. */
export function kbCoverage(): Record<string, number> {
  const byTable: Record<string, number> = {};
  for (const r of KB.beers) byTable[`beers_${r.table}`] = (byTable[`beers_${r.table}`] ?? 0) + 1;
  return {
    drugs: KB.drugs.length,
    brands: KB.drugs.reduce((s, d) => s + d.brands.length, 0),
    combos: KB.combos.length,
    classes: KB.classes.length,
    beersRules: KB.beers.length,
    ...byTable,
    acbListed: KB.drugs.filter((d) => d.acb > 0).length,
    strongAnticholinergics: KB.drugs.filter((d) => d.classes.includes("strong_anticholinergic")).length,
    cascades: KB.cascades.length,
    fridClasses: KB.frids.length,
    monitoringRules: KB.monitoring.length,
    sources: KB.sources.length,
    withRxcui: KB.drugs.filter((d) => d.rxcui !== null).length,
  };
}

export { matchDrug, matchDrugWithKb, cleanDrugName } from "./normalize";
export type { KnowledgeBase, KbDrug, KbSource, KbClass, KbCombo, DrugSelector, DrugMatch } from "./types";
